"""Recipient-aware equipment shopping and live field-supply previews.

Presentation only: purchases, ownership, equipment rules and item effects remain
authoritative in the existing engine.
"""

HELPERS = r'''var shopGearSlot=`all`,shopCompatibleOnly=!1,packView=`all`;
function focusShopPurchase(itemId){requestAnimationFrame(()=>{let row=Array.from(document.querySelectorAll(`#modal-root [data-shop-item]`)).find(row=>row.dataset.shopItem===itemId),button=row?.querySelector(`[data-buy]`);if(button?.disabled){row.focus({preventScroll:!0});row.scrollIntoView({block:`nearest`,inline:`nearest`,behavior:`instant`})}})}
function gearComparison(state,itemId,heroId){let item=K(itemId),hero=state.heroes.find(hero=>hero.id===heroId);if(!item||item.kind!==`equipment`||!hero)return null;let current=K(hero.equipment[item.slot]),keys=[...new Set([...Object.keys(item.stats??{}),...Object.keys(current?.stats??{})])],changes=keys.map(key=>({key,delta:(item.stats?.[key]??0)-(current?.stats?.[key]??0)})).filter(change=>change.delta!==0),gain=changes.some(change=>change.delta>0),loss=changes.some(change=>change.delta<0);return{heroId:hero.id,heroName:hero.name,role:hero.role,allowed:U(hero,item),currentId:current?.id??null,currentName:current?.name??`Empty`,changes,kind:gain&&loss?`tradeoff`:gain?`upgrade`:loss?`downgrade`:`equal`,owned:eqOwned(state,itemId),equipped:eqUsed(state,itemId),available:eqAvailable(state,itemId),fits:state.heroes.filter(candidate=>U(candidate,item)).map(candidate=>candidate.name)}}
function shopComparisonUI(state,itemId,heroId){let comparison=gearComparison(state,itemId,heroId);if(!comparison)return``;let item=K(itemId),label={tradeoff:`Trade-off`,upgrade:`Base stat gains`,downgrade:`Lower base stats`,equal:`Same base stats`}[comparison.kind];return`<div class="shop-comparison" data-shop-compare="${Q(heroId)}"><span class="shop-current">${Q(comparison.heroName)} wears: <strong>${Q(comparison.currentName)}</strong></span><span class="shop-offered-stats">${Q(eqT(item)||`No base stat bonus`)}</span>${comparison.allowed?`<span class="comparison-${comparison.kind}">${label}${comparison.changes.length?` · ${comparison.changes.map(change=>`<b class="${change.delta>0?`stat-up`:`stat-down`}">${Q(EQK[change.key]??change.key)} ${change.delta>0?`+`:``}${change.delta}</b>`).join(` · `)}`:``}</span>`:`<span class="shop-job-warning">Not usable by ${Q(comparison.heroName)} (${Q(comparison.role)}).</span>`}<span class="shop-copy-count">Owned ${comparison.owned} · Equipped ${comparison.equipped} · Available ${comparison.available}</span>${!comparison.allowed?`<span class="shop-fits">Fits: ${Q(comparison.fits.join(`, `)||`another job`)}. Purchase adds it to the shared pack.</span>`:``}</div>`}
function shopHeroTabs(state,heroId){return`<div class="hero-tabs shop-recipients" aria-label="Compare equipment for a traveler">${state.heroes.map(hero=>`<button data-shop-hero="${Q(hero.id)}" aria-pressed="${hero.id===heroId}" class="${hero.id===heroId?`active`:``}"><span><strong>${Q(hero.name)}</strong><small>${Q(hero.role)}</small></span></button>`).join(``)}</div>`}
function filteredEquipmentOffers(state,heroId){let hero=state.heroes.find(hero=>hero.id===heroId),order=[`weapon`,`body`,`head`,`mantle`,`charm`];return fe(state).filter(offer=>{let item=K(offer.itemId);if(storeFilter===`weapons`&&item.slot!==`weapon`||storeFilter===`armor`&&(item.kind!==`equipment`||item.slot===`weapon`))return!1;if(shopGearSlot!==`all`&&item.slot!==shopGearSlot)return!1;return!shopCompatibleOnly||item.kind!==`equipment`||U(hero,item)}).sort((left,right)=>{let a=K(left.itemId),b=K(right.itemId);return order.indexOf(a.slot)-order.indexOf(b.slot)||(b.tier??0)-(a.tier??0)||left.price-right.price})}
function fieldSupplyPreview(state,hero,itemId){let available=consumableValid(state,itemId,hero),result={available,kind:`none`,before:0,after:0,gain:0,unused:0,label:`No effect on this traveler right now.`};if(itemId===`REVIVAL_SALT`){let after=Math.max(1,Math.floor(hero.maxHp*.2));return{...result,kind:`hp`,before:hero.hp,after:available?after:hero.hp,gain:available?after:0,label:available?`HP 0 / ${hero.maxHp} → ${after} / ${hero.maxHp}`:`Only works on a fallen traveler.`}}if(hero.hp<=0)return{...result,label:`Revive this traveler first.`};let healing={POTION:60,HIGH_POTION:250,MENDING_BALM:120,CAMP_MEAL:Math.max(1,Math.floor(hero.maxHp*.3))}[itemId];if(healing!==void 0){let after=Math.min(hero.maxHp,hero.hp+healing),gain=after-hero.hp,unused=healing-gain;return{...result,kind:`hp`,before:hero.hp,after,gain,unused,label:gain?`HP ${hero.hp} / ${hero.maxHp} → ${after} / ${hero.maxHp} (+${gain})${unused?` · ${unused} healing unused`:``}`:`HP already full: ${hero.hp} / ${hero.maxHp}`}}if(itemId===`SPARK_TEA`||itemId===`DEEP_TEA`){let amount=itemId===`SPARK_TEA`?20:60,after=Math.min(hero.maxMp,hero.mp+amount),gain=after-hero.mp,unused=amount-gain;return{...result,kind:`mp`,before:hero.mp,after,gain,unused,label:gain?`MP ${hero.mp} / ${hero.maxMp} → ${after} / ${hero.maxMp} (+${gain})${unused?` · ${unused} MP unused`:``}`:`MP already full: ${hero.mp} / ${hero.maxMp}`}}let condition={ANTIDOTE:[`poison`,`Poison`],SOOTHING_DRAUGHT:[`sleep`,`Sleep`],CLEAR_TONIC:[`silence`,`Silence`]}[itemId];return condition?{...result,kind:`status`,label:available?`${condition[1]} → Cleared`:`No ${condition[1].toLowerCase()} to remove.`}:result}
function inventoryHealthUI(hero){let ratio=hero.maxHp?Math.max(0,Math.min(100,hero.hp/hero.maxHp)):0;return`<span class="inventory-health" data-current-health="${Q(hero.id)}"><span>${hero.hp}<i> / ${hero.maxHp} HP</i></span><span class="hp-track" aria-hidden="true"><span style="width:${ratio*100}%;background:${ratio<.25?`#d68a82`:`#9ec89a`}"></span></span></span>`}
function inventoryTargetUI(hero){let status=hero.hp<=0?`Fallen`:{poison:`Poisoned`,sleep:`Asleep`,silence:`Silenced`}[hero.status]||`Healthy`;return`<div class="inventory-target" data-inventory-target="${Q(hero.id)}" tabindex="-1" aria-live="polite"><strong>Use supplies on ${Q(hero.name)}</strong><span>${hero.hp} / ${hero.maxHp} HP · ${hero.mp} / ${hero.maxMp} MP · ${Q(status)}</span></div>`}
function inventoryBodyUI(state,heroId){let hero=state.heroes.find(hero=>hero.id===heroId),equipment=ee.filter(item=>item.kind===`equipment`&&((state.inventory[item.id]??0)>0||state.heroes.some(candidate=>Object.values(candidate.equipment).includes(item.id)))),supplies=Object.entries(state.inventory).filter(([id,count])=>count>0&&K(id)?.kind===`consumable`).sort((a,b)=>ee.indexOf(K(a[0]))-ee.indexOf(K(b[0]))),supported=[`POTION`,`HIGH_POTION`,`MENDING_BALM`,`ANTIDOTE`,`SOOTHING_DRAUGHT`,`CLEAR_TONIC`,`REVIVAL_SALT`,`CAMP_MEAL`,`SPARK_TEA`,`DEEP_TEA`];return`<div class="hero-tabs pack-recipients" aria-label="Choose a traveler for equipment and supplies">${state.heroes.map(candidate=>`<button class="${heroId===candidate.id?`active`:``}" data-pack-hero="${candidate.id}" aria-pressed="${heroId===candidate.id}">${Et(candidate.id,24)}<span><strong>${Q(candidate.name)}</strong><small>${candidate.hp}/${candidate.maxHp} HP · ${candidate.mp}/${candidate.maxMp} MP</small></span></button>`).join(``)}</div><div class="loadout"><strong>${Q(hero.name)} <small>${Q(hero.role)} · Lv ${hero.level}</small></strong><div class="inventory-resources">${inventoryHealthUI(hero)}${manaSummaryUI(hero)}</div><span>ATK ${hero.attack} · DEF ${hero.defense} · MDEF ${hero.magicDefense} · MAG ${hero.magic} · ACC ${hero.accuracy}</span><small>${Q(V(hero.job).trait)}</small><small>${Q(at(state,heroId))}</small></div><nav class="pack-views" aria-label="Pack view">${[[`all`,`All`],[`equipment`,`Equipment`],[`supplies`,`Supplies`]].map(([id,label])=>`<button class="small-button ${packView===id?`on`:``}" data-pack-view="${id}" aria-pressed="${packView===id}">${label}</button>`).join(``)}</nav><div class="pack-grid inventory-pack-grid ${packView===`all`?``:`mode-single`}"><div class="inventory-equipment" ${packView===`supplies`?`hidden`:``}>${eqUI(state,hero,equipment,heroId)}</div><section class="inventory-supplies" ${packView===`equipment`?`hidden`:``}><h3>Supplies</h3>${inventoryTargetUI(hero)}${supplies.map(([id,count])=>{let preview=fieldSupplyPreview(state,hero,id);return`<div class="inventory-row supply-row" data-supply-id="${Q(id)}"><span><strong>${Q(K(id)?.name??id)} <i>×${count}</i></strong><small>${Q(K(id)?.effect??``)}</small>${supported.includes(id)?`<small class="recovery-preview ${preview.available?`has-effect`:``}" data-recovery-preview="${Q(id)}">${Q(preview.label)}</small>`:``}</span>${supported.includes(id)?supplyUseUI(state,hero,id):``}</div>`}).join(``)||`<p class="muted">The pack is empty.</p>`}</section></div><p class="pack-hint">Owned equipment includes worn copies. Each wearer uses one owned copy. Supplies affect the selected traveler; recovery previews account for maximum HP and MP.</p><details class="pack-difficulty"><summary>Encounter difficulty · ${Q(DIFFL[state.difficulty??`easy`])}</summary><div class="shop-head"><span>Next encounter</span><button class="small-button" aria-label="Change difficulty" data-difficulty="cycle">${Q(DIFFL[state.difficulty??`easy`])}</button></div><p class="shop-intro">${difficultyDetails(state.difficulty)} Enemy strength changes; EXP and gold stay the same.</p></details>`}
function focusInventoryTarget(){requestAnimationFrame(()=>{let target=document.querySelector(`#modal-root [data-inventory-target]`);target?.focus({preventScroll:!0});target?.scrollIntoView({block:`nearest`,inline:`nearest`,behavior:`instant`})})}
'''

SHOP = r'''function shopUI(state){if([`Skill Shop`,`Magic Shop`].includes(state.message?.speaker))return magicShopUI(state,$);let context=state.area+`:`+state.message?.speaker;if(context!==storeContext){storeContext=context;storeFilter=`all`;shopGearSlot=`all`;shopCompatibleOnly=!1}let buying=shT===`buy`,equipment=state.message?.speaker===`Weapon Shop`,hero=state.heroes.find(hero=>hero.id===$)||state.heroes[0],offers=equipment?filteredEquipmentOffers(state,hero.id):fe(state);return`<p class="shop-intro">${Q(state.message?.text??``)}</p><div class="shop-head"><div class="hero-tabs"><button class="${buying?`active`:``}" data-shop-tab="buy">Buy</button><button class="${buying?``:`active`}" data-shop-tab="sell">Sell</button></div><strong class="shop-gold">${state.gold} gold</strong></div>${equipment&&buying?`${shopHeroTabs(state,hero.id)}<p class="shop-recipient-note">Compare with ${Q(hero.name)}'s current equipment. Buying adds copies to the shared pack; equip them from Items / Equipment.</p><nav class="store-categories" aria-label="Equipment category">${[`all`,`weapons`,`armor`].map(category=>`<button class="small-button ${storeFilter===category?`on`:``}" data-store-filter="${category}" aria-pressed="${storeFilter===category}">${category===`all`?`All equipment`:category===`weapons`?`Weapons`:`Armor & accessories`}</button>`).join(``)}</nav><nav class="gear-slot-filters" aria-label="Equipment slot">${[[`all`,`All slots`],...Object.entries(EQL)].map(([id,label])=>`<button class="small-button ${shopGearSlot===id?`on`:``}" data-gear-slot="${id}" aria-pressed="${shopGearSlot===id}">${Q(label)}</button>`).join(``)}</nav><button class="small-button compatible-toggle" data-compatible-only aria-pressed="${shopCompatibleOnly}">${shopCompatibleOnly?`Showing usable gear only`:`Show usable gear only`}</button>`:``}${buying?`<div class="shop-qty">Quantity: ${[1,5,10,`max`].map(quantity=>`<button class="small-button${shQ===quantity?` on`:``}" data-shop-qty="${quantity}">${quantity===`max`?`Max`:`×${quantity}`}</button>`).join(` `)}</div>`:``}<div class="shop-list">${buying?offers.map(offer=>{let item=K(offer.itemId),count=Math.min(shQ===`max`?99:shQ,99-(state.inventory[offer.itemId]??0),Math.floor(state.gold/offer.price)),limit=(state.inventory[offer.itemId]??0)>=99;return`<div class="inventory-row shop-offer" data-shop-item="${Q(offer.itemId)}" tabindex="-1" aria-label="${Q(item?.name??offer.itemId)} stock"><span><strong>${Q(item?.name??offer.itemId)}</strong><small>${offer.price} gold each${count>1?` · ${offer.price*count} total`:``}${item.kind!==`equipment`?` · carrying ${state.inventory[offer.itemId]??0}/99`:``}</small>${item.kind===`equipment`?shopComparisonUI(state,offer.itemId,hero.id):`<small>${Q(item.effect??``)}</small>`}${count<1?`<small class="shop-job-warning">${limit?`Pack limit reached`:`Not enough gold for one copy`}</small>`:``}</span><button class="small-button" data-buy="${Q(offer.itemId)}" ${count<1?`disabled`:``}>Buy${count>0?` ×${count}`:``}</button></div>`}).join(``)||`<p class="muted">No stock matches these filters. Choose another slot or show all usable jobs.</p>`:sL(state)}</div>`}
'''

CSS = r'''
.shop-recipients{margin-top:14px;flex-wrap:wrap;gap:5px}.shop-recipients button{flex:1;min-width:0;padding:8px}.shop-recipients span,.pack-recipients button>span{display:flex;flex-direction:column;gap:4px;min-width:0}.shop-recipients strong{font-size:12px;font-weight:normal;overflow-wrap:anywhere}.shop-recipients small{font-size:9px;color:#c7d9f6}.shop-recipient-note{font-size:10px!important;line-height:1.6;color:#c7d9f6}.gear-slot-filters{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}.gear-slot-filters .on,.compatible-toggle[aria-pressed=true],.pack-views .on{outline:1px solid #ffdfa0;border-color:#fff;background:#31549b}.compatible-toggle{margin:0 0 12px;font-size:10px}.shop-comparison{display:flex;flex-direction:column;gap:5px;margin-top:7px;font-size:10px;line-height:1.6}.shop-current{color:#c7d9f6}.shop-current strong{font-weight:normal;color:#fff}.shop-offered-stats{color:#ffdfa0}.shop-comparison b{font-weight:normal;white-space:nowrap}.shop-job-warning{color:#ffd29c}.shop-copy-count,.shop-fits{color:#c7d9f6}.comparison-tradeoff{color:#ffdfa0}.comparison-equal{color:#c7d9f6}.shop-offer{align-items:flex-start}.shop-offer>span{min-width:0}.shop-offer>[data-buy]{flex-shrink:0;margin-top:2px}.pack-recipients{flex-wrap:wrap}.pack-recipients button{min-width:0;flex:1}.pack-recipients strong{font-size:11px;font-weight:normal;overflow-wrap:anywhere}.pack-recipients small{font-size:8px;line-height:1.5;color:#c7d9f6}.inventory-resources{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:12px 0}.inventory-health{display:flex;flex-direction:column;gap:5px;font-size:13px;line-height:1.4}.inventory-health i{font-style:normal;color:#bed0f6;font-size:11px}.inventory-health .hp-track{display:block;height:6px;margin:0}.loadout>strong>small{font-size:11px;line-height:1.6;font-weight:normal;display:block;color:#c7d9f6;margin-top:4px}.pack-views{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}.inventory-pack-grid{align-items:start}.inventory-pack-grid.mode-single{grid-template-columns:1fr}.inventory-pack-grid>[hidden]{display:none!important}.inventory-equipment{min-width:0}.inventory-target{border:1px solid #758fc5;background:#102665;padding:10px;margin:0 0 10px;display:flex;flex-direction:column;gap:6px;outline-offset:3px}.inventory-target strong{font-size:12px;line-height:1.5;color:#ffdfa0;font-weight:normal}.inventory-target>span{font-size:11px;line-height:1.6}.inventory-target:focus-visible{outline:2px solid #ffe09c}.recovery-preview{font-size:10px!important;line-height:1.7;color:#b9c8e7}.recovery-preview.has-effect{color:#c4e5b9}.supply-row>span{min-width:0}.supply-row>[data-use]{flex-shrink:0}.pack-difficulty{border-top:1px solid #718ac0;margin-top:14px;padding-top:12px;font-size:11px}.pack-difficulty summary{cursor:pointer;line-height:1.7;color:#c7d9f6}.inventory-supplies h3{margin-top:0}
@media(max-width:760px){.shop-recipients strong{font-size:10px}.shop-recipients small{font-size:8px}.gear-slot-filters button{font-size:10px;padding:7px 9px}.shop-comparison{font-size:10px}.shop-offer>span>strong{font-size:12px}.shop-offer>[data-buy]{min-width:63px;padding:8px}.pack-recipients button{padding:8px 5px}.pack-recipients strong{font-size:10px}.pack-recipients small{font-size:8px;overflow-wrap:anywhere}.inventory-resources{gap:12px}.inventory-health{font-size:12px}.inventory-target>span{font-size:10px}.inventory-pack-grid{gap:15px}.pack-views button{flex:1}.supply-row>[data-use]{padding:8px;min-width:48px}.loadout>strong>small{font-size:10px}}
'''


def patch(source):
    labels = []

    def once(old, new, label):
        nonlocal source
        assert source.count(old) == 1, f'{label}: expected one anchor'
        source = source.replace(old, new, 1)
        labels.append(label)

    start = source.index('function shopUI(')
    end = source.index('var dfS=', start)
    once(source[start:end], HELPERS + SHOP, 'recipient-aware equipment shop and inventory presentation helpers')
    start = source.index('else if(mt===`inventory`){')
    end = source.index('}else mt===`wayfarer`?', start)
    once(source[start:end], 'else if(mt===`inventory`){n=`pack:`+$;t=Vt(`What we carry`,`SHARED PACK · EQUIPMENT & SUPPLIES`,inventoryBodyUI(e,$));', 'inventory shows live target resources and exact supply recovery previews')
    once('if(t.dataset.storeFilter){storeFilter=t.dataset.storeFilter,Ht();return}',
         'if(t.dataset.shopHero){$=t.dataset.shopHero,Ht();return}if(t.dataset.gearSlot){shopGearSlot=t.dataset.gearSlot;storeFilter=`all`;noRS=!0;Ht();return}if(t.hasAttribute(`data-compatible-only`)){shopCompatibleOnly=!shopCompatibleOnly;noRS=!0;Ht();return}if(t.dataset.packView){packView=t.dataset.packView;noRS=!0;Ht();return}if(t.dataset.storeFilter){storeFilter=t.dataset.storeFilter;shopGearSlot=`all`;noRS=!0;Ht();return}',
         'shop recipient slot compatibility and pack view filters retain quantity controls')
    once('if(t.dataset.use){Pt(X.useItem(t.dataset.use,$)?`${K(t.dataset.use)?.name} used on ${Dt($)}.`:`That item has no effect right now.`),Gt();return}',
         'if(t.dataset.use){let used=X.useItem(t.dataset.use,$);Pt(used?`${K(t.dataset.use)?.name} used on ${Dt($)}.`:`That item has no effect right now.`);Gt();if(used)focusInventoryTarget();return}',
         'item use updates live health and keeps keyboard focus on the recipient summary')
    once('Pt(n?`${K(t.dataset.buy)?.name} ×${n} added to the shared pack.`:`Not enough gold or the pack is full.`),Gt();return}',
         'Pt(n?`${K(t.dataset.buy)?.name} ×${n} added to the shared pack.`:`Not enough gold or the pack is full.`),Gt();if(n)focusShopPurchase(t.dataset.buy);return}',
         'completed purchases retain a keyboard cursor when the buy button becomes unavailable')
    once('</head>', '<style>' + CSS + '</style>\n</head>', 'responsive recipient comparisons and live inventory resource views')
    return source, labels
